import {hearButton} from './play-media.mjs';
import {helpers,acceptsAnswer} from './help-content.mjs';
import {guides,avatars,portrait,gardenScene} from './companions.mjs';
import {entrances,storyNodes} from './story-content.mjs';
import {ensureGarden,currentVisit,entranceById,storyDescribe} from './garden-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heading=(title,body)=>`<div class="page-heading"><a href="#home" class="back">← Back to the garden</a><h1>${esc(title)}</h1><p>${esc(body)}</p></div>`;
const named=(s,g)=>esc(s.replaceAll('{guide}',g.name));
const guideOf=s=>guides.find(g=>g.id===s.garden.guide);
export function companionLink(state){const g=guideOf(state);return `${portrait(g.id,true)}<span>With ${g.name}</span>`;}
export function guideRail(state,line){const g=guideOf(state);return `<aside class="guide-rail"><div class="guide-face">${portrait(g.id)}</div><h2>${g.name}</h2><p>${line?named(line,g):esc(g.hello)}</p><a href="#companions">Change companions</a><p class="tiny">Read, draw, talk, or take a break. You can find your own way.</p></aside>`;}
const pathIcon=id=>({creature:'✧',message:'✉',shelter:'⌂',cafe:'♧',paris:'✈'}[id]);
export function gardenHome(state,persist){
 const g=ensureGarden(state),v=currentVisit(state);
 return `<section class="garden-opening"><div class="garden-introduction"><p class="place-name">First morning in the Learning Garden</p><h1>The storm has passed.<br>The garden needs a hand.</h1><p>All our neighbors are safe. But the wind has scattered supplies, little hideaways need new ideas, and hungry visitors are arriving at the café.</p><p>Will you help us make the garden welcoming again? Gather curious foods, feed a neighbor, follow a message, or imagine a cozy shelter. Your guide will come with you.</p>${hearButton('The storm has passed. All our neighbors are safe. But the wind has scattered supplies, little hideaways need new ideas, and hungry visitors are arriving at the café. Will you help us make the garden welcoming again? Gather curious foods, feed a neighbor, follow a message, or imagine a cozy shelter. Your guide will come with you. Choose one small thing to try. There is no hurry, and you can ask for help or take a break.','Hear how our story begins')}<div class="hero-actions"><a class="primary" href="#cafe">Feed a hungry neighbor</a><a class="secondary" href="#storm">Find another way to help</a><a class="text-button" href="#companions">Choose your companions</a></div><p class="tiny">Choose one small thing. There is no hurry, and help is always welcome.</p><p class="tiny">${persist?'Your place is remembered in this browser.':'Saving is off. Your place lasts while this page stays open.'}</p></div><div class="garden-map">${gardenScene()}<button type="button" class="map-sign sign-creature" data-start-path="creature"><span>${pathIcon('creature')}</span>Follow a creature</button><button type="button" class="map-sign sign-message" data-start-path="message"><span>${pathIcon('message')}</span>Investigate a note</button><button type="button" class="map-sign sign-shelter" data-start-path="shelter"><span>${pathIcon('shelter')}</span>Make a hideaway</button></div></section><section class="welcome-companion"><div>${portrait(g.guide)}</div><blockquote><p>“${esc(guideOf(state).hello)}”</p><footer>${guideOf(state).name}, your companion <a href="#companions">Change</a></footer></blockquote><div class="explorer-stamp">${portrait(g.avatar,true)}<span>Your explorer</span></div></section>${v?`<div class="resume-strip"><span>${v.finished?'An idea is waiting to go with you.':`Your visit is waiting: ${esc(entranceById(v.entrance).title)}.`}</span><a class="secondary" href="#storm/${v.finished?'end':'play'}">${v.finished?'See your ending':'Continue our visit'}</a></div>`:''}<section class="paris-invitation"><img src="./paris-scene.svg" alt="An imagined Paris skyline, with the Eiffel Tower and a bridge over the Seine" width="800" height="450"><div><p class="place-name">A journey beyond the garden</p><h2>A postcard from Paris.</h2><p>A bookseller has stories to send our neighbors. Follow a note, become a word detective, and help a parcel find its way home.</p><a class="primary" href="#paris">Visit Paris together</a></div></section><section class="science-gate"><svg viewBox="0 0 160 160" aria-hidden="true"><path d="M80 12Q20 80 24 110Q28 150 80 150Q132 150 136 110Q140 80 80 12Z" fill="#abc4da"/><path d="M44 111Q80 82 116 111M48 126Q80 103 112 126" fill="none" stroke="#fffef9" stroke-width="5"/><circle cx="80" cy="59" r="10" fill="#fffef9"/></svg><div><h2>Puddles, frost, and a good question.</h2><p>The storm left water all around the garden. Before we make plans, let’s look closely: what happens when ice melts, and where does a puddle go? Explore with your guide and tell someone what you notice.</p><a class="primary" href="#science">Explore water together</a></div></section><section class="cafe-invitation"><div class="cafe-sketch" aria-hidden="true">☾<span>ALMOST-RIGHT CAFÉ</span>♧</div><div><p class="place-name">A warm welcome after the storm</p><h2>Let’s get the café cooking.</h2><p>Our hungry neighbors fancy dishes we haven’t got. Luckily, the cupboard holds some wonderfully odd alternatives. Find what each guest likes, make a plate, and head to the orchard when a jar runs low.</p><a class="primary" href="#cafe">Open the Almost-Right Café</a></div></section><section class="number-destination"><div class="number-emblem" aria-hidden="true">+ × ÷<br><span>✿</span></div><div><h2>Number Garden is still growing.</h2><p>Visit the seven math patches for check-ins, multiplication, picture playgrounds, and things to wonder about.</p><a class="primary" href="#facts">Explore all facts through 12 × 12</a><a class="secondary" href="#numbers">Explore Number Garden</a></div></section><p class="tiny garden-note">Explore together. Every path is open. No timer, grades, or need to finish everything.</p>`;
}
export function parisLanding(state){
 const v=currentVisit(state);
 return `${heading('The Paris Postcard','A make-believe visit to Paris, France. Our story notes are in English.')}<div class="story-layout paris-layout"><article class="story-sheet paris-welcome"><img class="paris-postcard-art" src="./paris-scene.svg" alt="An imagined Paris scene with rooftops, the Eiffel Tower, and a bridge over the Seine" width="800" height="450"><h2>Some stories are waiting across the river.</h2><p>Our garden neighbors could use a good story while they put things right after the storm. In Paris, a make-believe bookseller named Lucie is getting a parcel ready. You, Pip, Dot, and your guide can help it find its way.</p><p>Read a little at a time. Follow a note, look inside a word, and find the sentence that supports your idea. The passage stays with you while you think.</p><button class="primary" data-start-path="paris">${v?.entrance==='paris'&&!v.finished?'Continue our Paris visit':'Begin our Paris visit'}</button><p class="tiny">You can read, listen, talk, or skip a question. Pause whenever you like; this visit will keep its place.</p><details class="paris-parent-note"><summary>Grown-ups: reading along</summary><p>This is guided reading practice, with six small targets: finding a detail, word parts, vocabulary in context, inference, supporting evidence, and sequence. It does not measure oral decoding accuracy, fluency, or a reading level.</p><p>Sentence highlighting and read-aloud are recorded as support. Listening is welcome; it stays separate from reported independent reading. A postcard or retelling at the end is optional.</p><p>Design references: <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/21/Published" target="_blank" rel="noopener">IES foundational reading skills</a> and <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/14" target="_blank" rel="noopener">reading comprehension</a>. Paris and its landmarks are real; Lucie, the notes, and the errand are invented.</p></details></article>${guideRail(state,'{guide} says, “A word can be a clue. Let’s keep the message where we can see it and find out what it tells us.”')}</div>`;
}
export function companionPicker(state){
 const g=ensureGarden(state);
 return `${heading('Who’s coming with you?','Choose a guide and an explorer. You can change either whenever you like. No name or profile is needed.')}<section class="companion-section"><h2>Your guide</h2><p class="tiny">Every guide explores every path with you.</p><div class="companion-options">${guides.map(x=>`<button class="companion-option ${g.guide===x.id?'selected':''}" data-guide="${x.id}" aria-pressed="${g.guide===x.id}">${portrait(x.id)}<strong>${x.name}</strong><span class="tiny">${x.pronouns}</span><span>${esc(x.description)}</span><span class="choice-tick">${g.guide===x.id?'✓ Chosen':'Choose '+x.name}</span></button>`).join('')}</div></section><section class="companion-section"><h2>Your explorer</h2><p class="tiny">Choose the character you would like to be. This choice is separate from your guide.</p><div class="companion-options">${avatars.map(x=>`<button class="companion-option explorer-option ${g.avatar===x.id?'selected':''}" data-avatar="${x.id}" aria-pressed="${g.avatar===x.id}">${portrait(x.id)}<strong>${x.name}</strong><span>${x.description}</span><span class="choice-tick">${g.avatar===x.id?'✓ Chosen':'Choose this explorer'}</span></button>`).join('')}</div></section><div class="summary-links"><a class="primary" href="#storm">Explore the first morning</a><a class="secondary" href="#home">Back to the garden</a></div>`;
}
export function storyHub(state,pending){
 const v=currentVisit(state),g=state.garden,want=entranceById(pending);
 const confirmation=want&&v&&!v.finished?`<section class="visit-decision" role="region" aria-label="A visit is waiting"><h2>You have a visit waiting.</h2><p>You were exploring “${esc(entranceById(v.entrance).title)}.” You can continue, or begin “${esc(want.title)}” and keep the earlier visit here.</p><div class="summary-links"><button class="primary" data-resume-visit="${v.id}">Continue the waiting visit</button><button class="secondary" data-new-visit="${want.id}">Begin this new path</button></div></section>`:'';
 return `${heading('Choose a small way to help','After the storm, every good idea can make the garden a little more welcoming. Follow a neighbor’s tracks, read a message, imagine a shelter, open the café, or follow a reading errand in Paris. Each path is a whole visit; you can stop whenever you like.')}${confirmation}<div class="story-paths">${entrances.map(e=>`<article class="story-path path-${e.id}"><div class="path-sketch" aria-hidden="true">${pathIcon(e.id)}</div><h2>${esc(e.title)}</h2><p>${esc(e.invitation)}</p><button class="primary" data-start-path="${e.id}">${v&&!v.finished&&v.entrance===e.id?'Continue this path':g.visits.some(x=>x.entrance===e.id&&x.finished)?'Visit this path again':'Start here'}</button></article>`).join('')}</div>${g.visits.length?`<section class="visit-notebook"><h2>Your visits</h2><p class="tiny">Earlier visits stay here when you choose another entrance.</p><ul>${[...g.visits].reverse().map(x=>`<li><div><strong>${esc(entranceById(x.entrance).title)}</strong><span class="tiny">Visit ${x.id.split('-').at(-1)} · ${x.finished?'At an ending':'A place to return to'}</span></div><button class="secondary" data-resume-visit="${x.id}">${x.finished?'See the ending':'Continue'}</button></li>`).join('')}</ul></section>`:''}<a class="text-button" href="#numbers">Visit Number Garden instead</a>`;
}
function storyPicture(n){
 if(n.visual==='array')return `<div class="story-diagram"><div class="model-array" style="grid-template-columns:repeat(${n.diagram.cols},1fr)" role="img" aria-label="${n.diagram.rows} rows of ${n.diagram.cols} stones">${'<span></span>'.repeat(n.diagram.rows*n.diagram.cols)}</div></div>`;
 if(n.visual==='ruler'){
  const d=n.diagram,x=i=>24+i/d.max*360;
  return `<div class="story-diagram"><svg viewBox="0 0 410 105" role="img" aria-label="A ruler in centimetres, with a ribbon from ${d.start} to ${d.end}"><rect x="${x(d.start)}" y="15" width="${x(d.end)-x(d.start)}" height="24" rx="3" fill="#da8d8d"/><path d="M24 60H384" stroke="#183f39" stroke-width="2"/>${Array.from({length:d.max+1},(_,i)=>`<path d="M${x(i)} 55v12" stroke="#183f39"/><text x="${x(i)}" y="88" text-anchor="middle" font-size="14" fill="#183430">${i}</text>`).join('')}</svg></div>`;
 }
 return '';
}
const readingLabels=[['unobserved','Reading not observed'],['together','We read it together'],['listened','We listened to the passage'],['independent','I read it independently']];
function readingPassage(n,d){
 if(!n.readingText)return '';
 const tools=d.readingTools||{},index=tools.focus;
 const focusLabel={'paris-note':'Find a detail','paris-reread':'Look inside a word','paris-narrow':'Use nearby clues','paris-infer':'Connect two clues','paris-evidence':'Point to the words','paris-sequence':'Put events in order'}[n.id]||n.readingSkill;
 const spoken=[...n.readingText,n.prompt,...n.choices.map((c,i)=>`Choice ${i+1}. ${c}`)].join(' ');
 return `<section class="reading-passage" aria-labelledby="reading-passage-title"><div class="reading-passage-heading"><h3 id="reading-passage-title">From our Paris notebook</h3><span>${esc(focusLabel)}</span></div><p class="connected-text">${n.readingText.map((line,i)=>`<span class="reading-line ${index===i?'sentence-current':''}" id="reading-line-${i}" tabindex="-1" ${index===i?'aria-current="true"':''}>${esc(line)}</span>`).join(' ')}</p><div class="reading-tool-buttons"><button type="button" class="secondary" data-story-reading-tool="sentence-next" ${index===n.readingText.length-1?'disabled':''}>${index===null||index===undefined?'Follow one sentence':'Next sentence'}</button>${index!==null&&index!==undefined?'<button type="button" class="text-button" data-story-reading-tool="whole">Read without highlighting</button>':''}${hearButton(spoken,'Hear passage and question').replace('data-speak=', 'data-story-audio data-speak=')}</div><p class="tiny" id="reading-support-note">${tools.audioRequested?'You can listen, pause, and read the passage again.':tools.sentenceUsed?'The whole passage stays here while we follow one sentence at a time.':'Read silently, read together, or listen. You can return to any sentence.'}</p></section>`;
}
export function storyPage(state,d){
 const v=currentVisit(state),n=storyNodes[v.node],correct=acceptsAnswer(n,d.attempts.at(-1)),project=n.type==='project';
 const choices=project?(n.projectOptions||{creature:['A winding trail','A short trail','My own route'],message:['A picture','Words told to a helper','A picture and words'],shelter:['A tall doorway','A wide roof','My own shape']}[n.entrance]):null;
 return `${heading(entranceById(v.entrance).chapter||'First Morning',entranceById(v.entrance).title)}<div class="story-layout"><article class="story-sheet"><div class="story-chapter"><span>${esc(n.subject)} ${project?'· Imagine and make':'· A little investigation'}</span><span class="travelling-explorer">${portrait(state.garden.avatar,true)}</span></div><h2>${esc(n.title)}</h2><p class="story-body">${esc(n.body)}</p>${n.entrance==='paris'?'<img class="paris-story-strip" src="./paris-scene.svg" alt="A Paris skyline, showing the setting of our imaginary story" width="800" height="450">':''}${readingPassage(n,d)}${storyPicture(n)}<p class="story-question">${esc(n.prompt)}</p>${project?`<div class="project-invitation"><p>Your design, your choice. There is no right answer.</p><div class="project-choices" role="group" aria-label="Choose an idea">${choices.map(x=>`<button type="button" class="method ${d.designChoice===x?'selected':''}" data-design="${esc(x)}" aria-pressed="${d.designChoice===x}">${esc(x)}</button>`).join('')}</div>${d.designChoice?`<p class="design-note">An idea to take with you: <strong>${esc(d.designChoice)}</strong>.</p>`:''}<p class="tiny">Choosing or continuing records an invitation, not proof that you made something. You do not need to send us your work.</p><button class="primary" id="story-project-next">Take this idea to the ending</button></div>`:`${!correct?`<form id="story-answer-form" novalidate>${n.kind==='choice'?`<div class="choices story-choices" role="group" aria-label="Choose an answer">${n.choices.map((x,i)=>`<button type="button" class="choice ${d.choice===i?'selected':''}" data-story-choice="${i}" aria-pressed="${d.choice===i}">${esc(x)}</button>`).join('')}</div><button class="primary" type="submit">Try this idea</button>`:`<label for="story-answer" class="answer-label">Your answer${n.visual==='ruler'?' (centimetres)':''}</label><div class="answer-line"><input id="story-answer" type="text" inputmode="numeric" autocomplete="off" value="${esc(d.input)}" aria-describedby="story-error"><button type="submit" class="primary">Try my answer</button></div>`}<p class="tiny" id="story-error" role="alert">${esc(d.error||'')}</p></form>`:''}<div id="story-feedback" aria-live="polite">${correct?`<p class="feedback success">${esc(n.answerFeedback?.[d.attempts.at(-1)]||'That fits. What helped you find it?')}</p>`:d.attempts.length?`<p class="feedback">${esc(n.answerFeedback?.[d.attempts.at(-1)]||'An idea worth another look. You can try again, ask for a hint, or leave this question for now.')}</p>`:''}</div><div class="helper-offer ${d.attempts.length&&!correct?'after-miss':''}"><button class="secondary" id="story-help">Try a smaller example</button><p class="tiny">Your question waits here. A picture or little example might help.</p></div><div class="support-actions">${!d.hinted?'<button class="text-button" id="story-hint">A little hint</button>':''}${!d.revealed?'<button class="text-button" id="story-explain">Think it through together</button>':''}</div>${d.hinted?`<div class="hint"><strong>A little nudge</strong><p>${esc(n.hint)}</p></div>`:''}${d.revealed?`<div class="solution"><strong>One way to think about it</strong><p>${esc(n.explanation)}</p></div>`:''}${correct?`<fieldset class="story-method"><legend>How did you find it? Choose together.</legend><div class="method-grid">${[['knew','I knew it'],['worked','I worked it out'],['counted','I counted'],['together','We did it together']].filter(([id])=>n.entrance!=='paris'||id!=='counted').map(([id,label])=>`<button type="button" class="method ${d.method===id?'selected':''}" data-story-method="${id}" aria-pressed="${d.method===id}">${label}</button>`).join('')}</div></fieldset>`:''}`}
 <details class="reading-record" ${n.subject==='Reading'?'open':''}><summary>How did we read this part?</summary><p class="tiny">This is separate from solving the question. Reading together is welcome. Leave “not observed” if you did not notice.</p><div class="reading-options" role="group" aria-label="Reading observation">${readingLabels.map(([id,label])=>`<button type="button" class="method ${d.reading===id?'selected':''}" data-reading="${id}" aria-pressed="${d.reading===id}">${label}</button>`).join('')}</div></details>
 ${!project?`<div class="next-row">${correct?`<button class="primary" id="story-next" ${!d.method?'disabled':''}>Keep exploring</button>`:'<button class="text-button" id="story-skip">Leave this question for now</button>'}<a class="text-button" href="#home">Pause in the garden</a></div>`:'<a class="text-button" href="#home">Pause in the garden</a>'}<p class="tiny story-progress-note">${n.entrance==='paris'?(project?'Your postcard idea can wait for another day.':'This is reading practice. The passage can stay open, and you can take a break at any stop.'):'This path can finish on its own. No other path is required.'}</p></article>${guideRail(state,n.guide)}<aside class="story-wonder"><h3>Something to wonder</h3><p>${esc(correct||d.revealed||project?n.talk:'What do you notice? Where would you like to start?')}</p><p class="tiny">Talk, draw, or imagine together. The app does not score your explanation.</p></aside></div>`;
}
export function storyEnding(state){
 const v=currentVisit(state);if(!v?.finished)return storyHub(state);
 const e=entranceById(v.entrance),obs=state.garden.observations.filter(o=>o.visitId===v.id),idea=Object.values(v.drafts).find(d=>d.designChoice)?.designChoice;
 return `${heading('A place to pause.','One path is a whole visit. You can stop here, take an idea with you, or follow a different curiosity.')}<div class="story-layout"><article class="story-sheet story-ending"><span class="ending-leaf" aria-hidden="true">✧</span><h2>${esc(e.ending.title)}</h2><p class="story-body">${esc(e.ending.body)}</p><section class="takeaway"><h3>${esc(e.ending.projectTitle)}</h3><p>${esc(e.ending.project)}</p>${idea?`<p class="design-note">Your chosen idea: ${esc(idea)}.</p>`:''}<p class="tiny">Entirely optional. Nothing to upload, photograph, or hand in.</p></section><div class="summary-links"><a class="primary" href="#home">Back to the Learning Garden</a><a class="secondary" href="#storm">Follow another curiosity</a></div><details><summary>Grown-ups: what we noticed on this visit</summary>${obs.map(storyEvidence).join('')}<a href="#notes">All grown-up notes</a></details></article>${guideRail(state,'{guide} says, “There’s always more to wonder about. This is a good place to pause.”')}</div>`;
}
function storyEvidence(o){return `<div class="evidence-item"><strong>${esc(o.title)} — ${esc(storyDescribe(o))}</strong><p>${esc(o.prompt)}</p>${o.readingSkill?`<p>Reading focus: ${esc(o.readingSkill)}. ${o.priorPassageSeen?'This passage was encountered earlier; this is rereading practice.':'This visit introduced this passage.'}${o.readingTools?.audioRequested?' Read-aloud requested; playback was not verified.':''}${o.readingTools?.sentenceUsed?' Sentence focus used.':''}${o.readingTools?.supportUncertain?' Earlier reading support could not be determined.':''}</p>`:''}<p>${o.status==='invitation'?'Project invitation only.':`Answers tried: ${esc(o.attempts.map(v=>o.choices?.[v]??v).join(', ')||'None')}.`}${o.helpUsed?' Smaller example opened.':''}${o.hinted?' Hint opened.':''}${o.revealed?' Explanation opened.':''}${o.familiar?' This task was seen on an earlier visit.':''}${o.knownFact?' A related fact appeared earlier.':''}${o.priorExposureUnknown?' Earlier fact familiarity was not recorded.':''}</p>${o.helper?`<p>Helper example: ${esc(helpers[o.nodeId]?.title||o.helper.exampleId)}. Example answers tried: ${esc(o.helper.attempts.map(v=>helpers[o.nodeId]?.choices?.[v]??v).join(', ')||'None')}. ${o.helper.revealed?'Example explanation opened. ' :''}Representation${o.helper.modelUsed?' used':' not used'}: ${o.helper.steps||0} steps currently counted${o.helper.spotlight!==null?', a detail spotlighted':''}.</p>`:''}${o.method?`<p>Answer method: ${esc({knew:'Reported knowing it',worked:'Worked it out',counted:'Counted',together:'Worked together'}[o.method]||o.method)}.</p>`:''}<p>Reading: ${o.reading==='independent'?'reported read independently':o.reading==='together'?'read together':o.reading==='listened'?'reported listened to the passage':'not observed'}.</p>${o.designChoice?`<p>Unscored design idea: ${esc(o.designChoice)}.</p>`:''}</div>`;}
export function gardenNotes(state){
 const g=ensureGarden(state);
 return `<section class="panel"><h2>Garden visits</h2><p class="tiny">The Paris visit is guided reading practice. Its notes describe individual comprehension/word-meaning tasks and reported reading support; no oral decoding accuracy, fluency, or reading level is inferred.</p><p>${g.visits.length} visit${g.visits.length===1?'':'s'} · ${g.visits.filter(v=>v.finished).length} at an ending</p><p class="tiny">Story tasks include context and guide prompts. Answer methods describe extra help, not a baseline assessment. Reading observations are reported separately. Unvisited subjects remain unknown; a project invitation does not establish completion or mastery.</p>${g.visits.length?`<div class="summary-links"><a class="secondary" href="#storm">Return to a visit</a><a href="#companions" class="text-button">Change companions</a></div>`:'<a href="#storm">Explore First Morning</a>'}</section><details class="panel"><summary>Story observations (${g.observations.length} recorded)</summary>${g.observations.map(storyEvidence).join('')||'<p>No story observations recorded yet.</p>'}</details>`;
}
